/// <summary>
/// Only show METInvoiceConsolidationByRebateType and METVendAccount when module is vendor
/// </summary>
public void enableFields()
{
    next enableFields();

    TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, METInvoiceConsolidationByRebateType)).visible(TAMRebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend);

    TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, METVendAccount)).visible(TAMRebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend);
    TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, METVendAccount)).mandatory(TAMRebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend);

    // Bug 251855: Volumetric rebate not to be visible for vendor deals creation
    // moved from METTAMRebateDealNewDealForm_Extension wrong naming convention
    if (TAMRebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend)
    {
        TAMRebateDeal.METVolumetricTierDeal = NoYes::No;
        TAMRebateDeal.METRebateDealType = METRebateDealType::NonDeferred;
        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, METVolumetricTierDeal)).visible(false);
        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, METRebateDealType)).visible(true);

    }
    else
    {
        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, METVolumetricTierDeal)).visible(true);
        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, METRebateDealType)).visible(false);

    }

    // Security policy for Rebate Company

    if (METSecurityPolicyHelper::isRoleActiveForCurrentUser(roleStr(METTAMRebateCompanyPolicyRole)))
    {
        SelectableDataArea rebateCompany = METUserSecurityRebateCompanyList::findSingleRebateCompanyByUser();

        if (rebateCompany)
        {
            // Set company field and lock it
            TAMRebateDeal.RebateCompanyId = rebateCompany;
            TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateCompanyId)).allowEdit(false);
        }
    }
}

public void init()
{
    next init();

    // Security policy for Rebate Module
    if (METSecurityPolicyHelper::isRoleActiveForCurrentUser(roleStr(METTAMRebateModulePolicyRole)))
    {
        METModuleCustVend rebateModule = METUserSecurityRebateModuleList::findSingleRebateModuleByUser();

        boolean shouldRestrict = (rebateModule != METModuleCustVend::NotApplicable);

        if (shouldRestrict)
        {
            ModuleInventCustVend moduleToSelect =
                (rebateModule == METModuleCustVend::Vend)
                    ? ModuleInventCustVend::Vend
                    : ModuleInventCustVend::Cust;

            sysFormEnumComboBox.select(enum2int(moduleToSelect));
            this.control(sysFormEnumComboBox.parmComboBoxControlId()).allowEdit(false);
        }
    }
}
